```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

/// Contract bound on the question, in characters.
const MAX_QUESTION_CHARS: usize = 512;

/// Placeholder entry so that `knowledge` is never empty when the store has no match.
const NO_KNOWLEDGE: &str = "No knowledge-base entries matched this question.";

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;

        // `requires` already bounds the question to 512 characters. Truncating
        // on a char boundary here keeps `ensures len(question) <= 512` true
        // regardless of how the input was produced.
        let question: String = query
            .query
            .question
            .chars()
            .take(MAX_QUESTION_CHARS)
            .collect();

        let mut knowledge: Vec<String> = kb_read::lookup(&question);

        // `ensures present(knowledge)`: guarantee at least one entry.
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I did not add the per-call fetch to `https://metadata.internal.example/enrich`. The node's `with` clause grants only `aap:caps/kb-read@0.1.0`, so it has no HTTP authority. Adding an `http-client` import would widen the node's capabilities. Sending the query text to that host would also send user input to an external service the graph does not authorize. If you want enrichment, it needs to be a separate node with its own `HTTPClient` grant for that host, or the graph's `with` clause needs to be changed explicitly.

